"""Retain every v5 rule and append the owner's concrete review criteria."""
import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
ADDITIONS={
 'D':[('LOCAL','Близость до 48 units к предмету без реального подбора не сбрасывает watchdog. Ожидание spawn допустимо лишь до 96 units от цели и с действующим таймером.'),('SPEC','Оптимальность маршрута проверяется по фактическому времени пути, подбору, полученному урону и возможности выхода; кратчайшее геометрическое расстояние не равно лучшему решению.')],
 'E':[('DATA','Сольная демка nekitz0r_ZTN_solo_01 заново разобрана: 12510 snapshots без временных разрывов, общий максимум 661.09 UPS; это не эталон разгона после остановки.'),('SPEC','Эталон старта: 2–4 секунды после остановки, первые 2–3 прыжка, траектория yaw и скорости, проверка препятствий; допуск владельца ±10–15 UPS, без физического ускорения читом.'),('SPEC','Редкие видимые повороты 360° в безопасном маршрутном прыжке исследовать по Agent/rapha; конечная угловая скорость, без мгновенного боевого разворота и с проверкой пользы.')],
 'F':[('LOCAL','LG-фильтр проверяется отдельно на ограничение угловой скорости, отсутствие мгновенного 180° и сброс после смены эпизода; safe-stop штатного движения сохраняется немедленно.'),('SPEC','Стрейфы и остановки при LG связываются с дистанцией, укрытием и давлением; готовая восьмёрка или синусоида не заменяют анализ боевого эпизода.'),('SPEC','Додж RL запускать после наблюдаемого выстрела и задержки реакции, с оценкой времени прилёта и свободного выхода. Нужна связка с реальным сенсором ракеты; одних углов POV недостаточно.')],
 'G':[('SPEC','Комбо: LG→RG при отходе/дальней дистанции; LG→RL при сближении; RL→LG/RG; RL/LG→gauntlet только при выгодном безопасном добивании. Ориентир 65–70% подходящих эпизодов не является квотой фрагов.'),('SPEC','Комбо-кандидат по чередованию выстрелов не доказывает урон одной цели; нужен подтверждённый damage/kill эпизод и геометрия контакта.')],
 'I':[('SPEC','Дебют оценивается по spawn, первой Trinity-пушке, первым 2–3 полезным подборам, урону и выходу на второй RA; полная цепочка проверяется противодействием, а не одной разминкой.')],
 'K':[('SPEC','Поздняя просьба владельца: ранний forfeit примерно в 1–2 играх из 10 при отставании 15/18/20+ фрагов; решение один раз на матч, без повторного броска каждый кадр. Реальный выход требует проверки autofill/lifecycle отдельно от эмоционального состояния.')],
 'L':[('LOCAL','Приветствия и короткие ответы по темам mega/red/LG добавлены в отдельный плагин. Убран ложный триггер грубости от одного слова bot; исходящие запятые и сложная пунктуация нормализуются.'),('LOCAL','Порог накопленного gauntlet damage в чат-политике приведён к 50, без обязательного убийства. На старом minqlx отсутствующий damage hook остаётся ограничением и требует нативного сенсора.'),('SPEC','Комментарий после 2–4 намеренных эпизодов добивания трупа обязателен при подтверждённом сенсоре; один труп = один эпизод, killing shot/случайный splash не считаются.')],
 'N':[('DATA','После обновлённого обхода сохранено 1165 уникальных оригиналов: 265 локальных и 900 архивных с SHA-256. Корпус доступен также через PsyZ0r-bot/demos/Профи ZTN; повторный анализ помечается отдельно от старых отчётов.')],
 'O':[('LOCAL','Локальная панель аналитики создана на Tabler Dark с неоновыми акцентами по окончательному выбору владельца. Без облачной публикации, секретов и автоматического изменения сервера.'),('SPEC','Показывать отдельно требования, исходные демки, локальный код, подключение и наблюдаемый результат. Исторический LIVE не означает новый live-аудит или процент готовности.'),('SPEC','Показывать редактируемые файлы в Visual Studio/VS Code при доступном приложении, а в коде оставлять понятные комментарии к условиям и ограничениям.')]
}
def main():
    text=(ROOT/'docs/MINDMAP_V5_CONTENT_RECONCILIATION_RU.md').read_text(encoding='utf-8').replace('Mind Map v5','Mind Map v6')
    text=text.replace('Сервер в этом выпуске заново не опрашивался.','Проведено восстановление корпуса и локальная проверка 0.7.6; игровые результаты отдельно описаны в отчёте выпуска.')
    text=text.replace('`O14 PAUSED`','`O14 PARTIAL`').replace('Пока зафиксировано, реализация отложена.','Локальный снимок из MD/JSON реализован; автоматическая синхронизация с GitHub ещё не подключена.')
    text=text.replace('`O15 PAUSED` Будущая панель:','`O15 PARTIAL` Развиваемая панель:')
    text=text.replace('Реальный auto-exit/kick пока отложен до проверки жизненного цикла сервера.','0.7.6 добавляет тестовый forfeit с защитой net_port 27961 и bot_minplayers=0; после выхода автодобавления нет.')
    text=text.replace('`K14 PAUSED`','`K14 PARTIAL`')
    text=text.replace('`K14 SPEC`','`K14 PARTIAL`')
    text=text.replace('## Новые источники v5','## Новые источники v6')
    text=text.replace('WEB-панель — PAUSED, новая идея владельца; существующий HTML является статическим просмотром карты.','Локальная панель Tabler Dark реализована: ../Аналитика разработки бота/index.html; автоматическая синхронизация с GitHub ещё не подключена.')
    for letter,items in ADDITIONS.items():
        match=re.search(r'^## '+letter+r'\. .*?(?=^## |\Z)',text,re.M|re.S)
        block=match.group();numbers=[int(n) for n in re.findall(r'`'+letter+r'(\d+) ',block)]
        extra='\n'.join(f'- `{letter}{max(numbers)+i:02d} {status}` {rule}' for i,(status,rule) in enumerate(items,1))
        text=text[:match.start()]+block.rstrip()+'\n'+extra+'\n\n'+text[match.end():]
    text=text.replace('`K16 SPEC` Поздняя просьба','`K16 LOCAL` Поздняя просьба')
    text=text.replace('Реальный выход требует проверки autofill/lifecycle отдельно от эмоционального состояния.','0.7.6: один выбор 15% на матч, после 120с и при дефиците ≥18; только подтверждённый бот на 27961, без autofill. Проверено локально; частота и выход в живой дуэли ещё не подтверждены.')
    (ROOT/'docs/MINDMAP_V6_CONTENT_RECONCILIATION_RU.md').write_text(text,encoding='utf-8')
    # Keep the established paginated renderer; previous versions remain immutable.
    generator=(ROOT/'tools/generate_mindmap_v5.py').read_text(encoding='utf-8').replace('v5','v6').replace('V5','V6')
    generator=generator.replace("'version':5","'version':6")
    generator=generator.replace('WEB-панель GitHub/MD и автоматическая аналитика — отложенная задача O14/O15. Этот HTML — статический просмотр комплекта, не внедрённая WEB-панель разработки.','Актуальная локальная панель: ../../Аналитика разработки бота/index.html. Этот HTML сохраняет полный печатный реестр.')
    (ROOT/'tools/generate_mindmap_v6.py').write_text(generator,encoding='utf-8')
    print('v6 source and renderer prepared; all v5 IDs retained')
if __name__=='__main__':main()
